import java.lang.reflect.Constructor;

public class Main {
    static class Cat {
        {t} value;

        Cat({t} value) {
            this.value = value;
        }
    }

    public static void main(String[] args) throws Exception {
        Constructor<?> 产房 = Cat.class.getDeclaredConstructor({t}.class);
        System.out.println("产房收的是：" + 产房.getParameterTypes()[0].getSimpleName());
    }
}
